"use client";
import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";

export default function AdminDashboard() {
  const { data: session } = useSession();
  const [data, setData] = useState<any>(null);

  useEffect(() => {
    fetch("/api/admin/stats").then(res => res.json()).then(setData);
  }, []);

  if (!data) return <div className="p-10 text-teal-400 animate-pulse">Sistem verileri yükleniyor...</div>;

  return (
    <div className="space-y-10">
      <header>
        <h1 className="text-4xl font-black text-fuchsia-500 uppercase tracking-tighter italic">Terminal Kontrol</h1>
        <p className="text-teal-400/50 text-sm">Sistemdeki tüm kullanıcıların performans analizi.</p>
      </header>
      
      {/* GRAFİKLER */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {data.stats.map((user: any) => (
          <div key={user.id} className="bg-[#0E153A] border border-teal-400/20 p-6 rounded-[2rem] shadow-xl">
            <div className="flex justify-between items-center mb-4">
              <span className="text-white font-bold tracking-wide">{user.name}</span>
              <span className="text-fuchsia-400 font-black text-2xl">{user.percentage}%</span>
            </div>
            <div className="w-full h-3 bg-black/40 rounded-full overflow-hidden border border-white/5">
              <div 
                className="h-full bg-gradient-to-r from-fuchsia-600 to-teal-400 transition-all duration-1000 ease-out" 
                style={{ width: `${user.percentage}%` }} 
              />
            </div>
            <p className="mt-3 text-[10px] text-teal-500/50 uppercase font-bold tracking-widest">Veri Noktası: {user.total} Görev</p>
          </div>
        ))}
      </div>

      {/* MESAJLAR */}
      <div className="bg-[#0E153A]/50 border border-teal-400/10 rounded-[2rem] overflow-hidden backdrop-blur-md">
        <div className="p-5 bg-teal-400/10 border-b border-teal-400/10 text-teal-400 font-bold uppercase text-xs tracking-[0.2em]">
          Gelen İletişim Formları
        </div>
        <div className="divide-y divide-teal-400/5">
          {data.messages.map((m: any) => (
            <div key={m.id} className="p-6 hover:bg-white/5 transition-colors group">
              <div className="flex justify-between mb-2">
                <span className="text-fuchsia-400 font-bold text-sm">{m.name}</span>
                <span className="text-[10px] text-white/20 italic">{new Date(m.createdAt).toLocaleDateString()}</span>
              </div>
              <p className="text-white/70 text-sm leading-relaxed">{m.message}</p>
              <p className="text-[10px] text-teal-500/40 mt-2">{m.email}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}